import{_ as r,C as i,o as n,c as l,ao as s,j as t,a as c,E as o,w as d}from"./chunks/framework.uwoVz_rB.js";const k=JSON.parse('{"title":"Package","description":"","frontmatter":{},"headers":[],"relativePath":"reference/package.md","filePath":"reference/package.md","lastUpdated":null}'),p={name:"reference/package.md"},m={class:"jldocstring custom-block",open:""};function g(h,e,u,_,f,b){const a=i("Badge");return n(),l("div",null,[e[4]||(e[4]=s('<h1 id="Package" tabindex="-1">Package <a class="header-anchor" href="#Package" aria-label="Permalink to &quot;Package {#Package}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Status — Reference</p><p>Mirrors drmTMB&#39;s <a href="https://itchyshin.github.io/drmTMB/reference/index.html" target="_blank" rel="noreferrer">Package</a> (1 item in drmTMB). The <code>DRM</code> module overview.</p></div>',2)),t("details",m,[t("summary",null,[e[0]||(e[0]=t("a",{id:"DRM",href:"#DRM"},[t("span",{class:"jlbinding"},"DRM")],-1)),e[1]||(e[1]=c()),o(a,{type:"info",class:"jlObjectType jlModule",text:"Module"})]),e[3]||(e[3]=s('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DRM</span></span></code></pre></div><p><code>DRM.jl</code> — a Julia engine for distributional regression models, the Julia twin of the R package <strong>drmTMB</strong>. Mirrors the gllvmTMB → GLLVM.jl move.</p><p>The package covers univariate and bivariate distributional regression across some twenty response families, with random, phylogenetic, spatial, pedigree and supplied-matrix structure. Its origin is the <strong>q=4 phylogenetic bivariate location–scale model (PLSM)</strong> — the selling-point model of drmTMB (Nakagawa et al. 2025 MEE, Model 5). That marginal is a sparse <strong>augmented-state Laplace approximation</strong> with an <strong>exact O(p) gradient</strong> (implicit-function / TMB-style, via Takahashi selected inverse — never forms a dense p×p Σ_phy), optimised by LBFGS with a fast-path-then-robust mode-finder.</p><p>For what is implemented and how far each route is tested, see the capability matrix in the documentation. Measured comparisons against drmTMB, with their run conditions, live in <code>report/comparison-grid.md</code> and <code>HANDOVER.md</code> §2; they are specific to the model and data measured and are deliberately not quoted as figures here (HANDOVER.md §2, &quot;Do NOT oversell&quot;).</p><p>NOTE (see HANDOVER.md): the engine files were migrated as the poc&#39;s script-style includes (chain: fit_q4_sparse_tmb → fit_ml_q4 → sparse_em_fit → sparse_aug_plsm → sparse_phy / takahashi_selinv). Inference (Wald + profile + parametric bootstrap) is wired in <code>src/inference.jl</code>. <strong>Public / included on tip:</strong> opt-in REML (<code>src/reml_q4.jl</code>,<code>drm(method = :REML)</code>; restricted correction covers all four among-axis axes — see #11) and the conjugate-EM Gaussian phylo-mean solver (<code>src/location_only.jl</code>,<code>algorithm = :em</code> — see #12). <strong>#13 decision gate FAIL (2026-08-01):</strong> natural-gradient EM stalls vs sparse TMB on q4_p100 — do <strong>not</strong> expose <code>algorithm = :natgrad</code>; the reusable Fisher metric lives in <code>src/lc_metric.jl</code>. <strong>Still experimental (not wired):</strong> SQUAREM EM, trust-region &amp; line-search E-steps, dense q=4 EM, warm-start fit variants, and the leftover <code>src/experimental/location_only.jl</code> / <code>fit_em_natgrad.jl</code> prototypes — do not treat that directory as the public REML / <code>:em</code> surface.</p>',5)),o(a,{type:"info",class:"source-link",text:"source"},{default:d(()=>[...e[2]||(e[2]=[t("a",{href:"https://github.com/itchyshin/DRM.jl/blob/44a6abc9a578b44202584af904cb7f8e6aac102c/src/DRM.jl#L1-L35",target:"_blank",rel:"noreferrer"},"source",-1)])]),_:1})])])}const v=r(p,[["render",g]]);export{k as __pageData,v as default};
